<script setup lang="ts">
import {computed,ref} from 'vue';
import {ElDialog,ElButton,ElMessage} from 'element-plus';
import SkillParameters from './SkillParameters.vue';
import {usePhase1,p1ConfigError} from '@/pinia/phase1';
import {agentWorkData} from '@/pinia/agentWork';
import type {P1SkillId,P1Config} from '@/views/AgentWork/interface';
import {phaseSkills} from './catalog';import {taskParameters,taskRule} from './ruleLanguage';import RuleAssistant from './RuleAssistant.vue';
const props=defineProps<{projectId:string;taskId:P1SkillId;draftConfig?:P1Config;draftOnly?:boolean}>();const emit=defineEmits<{close:[];saved:[config:P1Config]}>();const s=usePhase1();const work=agentWorkData();const baseline=s.config(props.projectId).version;const draft=ref(props.draftConfig?JSON.parse(JSON.stringify(props.draftConfig)) as P1Config:s.config(props.projectId));draft.value.missingPass??={origin:false,destination:false};const task=computed(()=>phaseSkills.find(t=>t.id===props.taskId)!);const error=ref('');const parameters=computed(()=>taskParameters(draft.value,props.taskId).filter(parameter=>!parameter.key.endsWith('enabled')));
function save(){error.value=p1ConfigError(draft.value);if(error.value)return;if(props.draftOnly){emit('saved',draft.value);emit('close');return;}if(!s.saveConfig(props.projectId,draft.value,baseline)){error.value=s.error;return;}const p=work.projects.find(p=>p.id===props.projectId);if(p)p.skillIds=[...(p.skillIds||[]).filter(x=>!phaseSkills.some(t=>t.id===x)),...s.config(props.projectId).selectedSkills];ElMessage.success('任务规则与项目配置已更新');emit('close');}
</script>
<template><ElDialog :model-value="true" :title="draftOnly?'配置技能':'编辑系统任务'" width="640px" style="max-width:calc(100vw - 32px)" :close-on-click-modal="false" @close="emit('close')"><div class="monitor-form"><label>任务名称<input :value="task.name" readonly aria-label="任务名称"/></label><p v-if="draftOnly" class="p1-muted">确认后更新项目草稿，点击项目“完成”后保存生效。</p><h3>任务说明与规则</h3><div class="rule-narrative"><p>{{task.description}} {{taskRule(draft,taskId)}}</p><p v-for="parameter in parameters.filter(p=>p.key==='filter-rule'&&p.value!=='使用默认规则')" :key="parameter.key">过滤规则：{{parameter.note}}</p></div><SkillParameters v-model="draft" :task-id="taskId"/><RuleAssistant :config="draft" :scope="taskId" @confirm="draft=$event.config"/><p class="p1-error" role="alert">{{error}}</p></div><template #footer><ElButton @click="emit('close')">取消</ElButton><ElButton type="primary" @click="save">{{draftOnly?'确认配置':'保存任务'}}</ElButton></template></ElDialog></template>
<style scoped>
.monitor-form{font-size:14px;line-height:1.6}.monitor-form label,.monitor-form input{display:block;width:100%}.monitor-form input{margin-top:6px;padding:8px 10px;border:1px solid #ddd;border-radius:5px;background:#f7f7f7}.monitor-form h3{font-size:13px;margin:14px 0 6px;font-weight:600}.monitor-form p{margin:5px 0}.rule-parameters{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));column-gap:24px;margin:6px 0 4px;padding:4px 0;border-top:1px solid #e5e7eb;border-bottom:1px solid #e5e7eb}.rule-parameters>div{display:flex;align-items:baseline;justify-content:space-between;gap:12px;padding:7px 0;min-width:0}.rule-parameters dt{color:#667487;font-size:13px;flex-shrink:0}.rule-parameters dd{margin:0;text-align:right;overflow-wrap:anywhere}.rule-parameters strong{font-weight:500}.rule-help{font-size:12px;color:#667487;margin-top:7px}.rule-help summary{cursor:pointer;width:fit-content}.rule-help p{margin:6px 0}.rule-help span{color:#344054}@media(max-width:560px){.rule-parameters{grid-template-columns:1fr}}
</style>
